31	func (s *Server) checkLimits(ctx context.Context, user utils.User) (int64, *extProcPb.ProcessingResponse, error) {
32		if user.Rpm == 0 {
33			user.Rpm = int64(DefaultRPM)
34		}
35		if user.Tpm == 0 {
36			user.Tpm = user.Rpm * int64(DefaultTPMMultiplier)
37		}
38	
39		code, err := s.checkRPM(ctx, user.Name, user.Rpm)
40		if err != nil {
41			errorCode := ""
42			if code == envoyTypePb.StatusCode_TooManyRequests {
43				errorCode = ErrorCodeRateLimitExceeded
44			}
45			return 0, generateErrorResponse(
46				code,
47				[]*configPb.HeaderValueOption{{Header: &configPb.HeaderValue{
48					Key: HeaderErrorRPMExceeded, RawValue: []byte("true"),
49				}}},
50				err.Error(), errorCode, ""), err
51		}
52	
53		rpm, code, err := s.incrRPM(ctx, user.Name)
54		if err != nil {
55			return 0, generateErrorResponse(
56				code,
57				[]*configPb.HeaderValueOption{{Header: &configPb.HeaderValue{
58					Key: HeaderErrorIncrRPM, RawValue: []byte("true"),
59				}}},
60				err.Error(), "", ""), err
61		}
62	
63		code, err = s.checkTPM(ctx, user.Name, user.Tpm)
64		if err != nil {
65			errorCode := ""
66			if code == envoyTypePb.StatusCode_TooManyRequests {
67				errorCode = ErrorCodeRateLimitExceeded
68			}
69			return 0, generateErrorResponse(
70				code,
71				[]*configPb.HeaderValueOption{{Header: &configPb.HeaderValue{
72					Key: HeaderErrorTPMExceeded, RawValue: []byte("true"),
73				}}},
74				err.Error(), errorCode, ""), err
75		}
76	
77		return rpm, nil, nil
78	}
