114	
115	// enforceModelRPS atomically increments the per-model RPS counter and rejects the request
116	// if the new value exceeds the limit.
117	func (s *Server) enforceModelRPS(ctx context.Context, model string, routingCtx *types.RoutingContext) *extProcPb.ProcessingResponse {
118		if routingCtx.ConfigProfile == nil || routingCtx.ConfigProfile.RequestsPerSecond <= 0 {
119			return nil
120		}
121		limit := routingCtx.ConfigProfile.RequestsPerSecond
122		newVal, err := s.modelRateLimiter.Incr(ctx, modelRPSKey(model), 1)
123		if err != nil {
